/*
 * A320340  Heinz numbers of double-free integer partitions.
 * https://oeis.org/A320340
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n‑th integer satisfying: if prime(m) | a(n) then
 *            prime(2m) ∤ a(n)
 * Range:     u8 n <= 203, u16 n <= 9914, u32 n <= 9914, u64 n <= 9914,
 *            u128 n <= 9914, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by incremental testing of integers and a simple
   prime sieve that is extended as needed. */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

/* --- Global state ---------------------------------------------- */

static uint64_t *prime_list   = NULL;   /* array of primes */
static int *prime_index_arr   = NULL;   /* prime_index_arr[p] = 1‑based index of p, 0 if not prime */
static size_t prime_count     = 0;      /* number of primes in prime_list */
static uint64_t prime_limit   = 0;      /* smallest prime in prime_list > prime_limit is not present */

static seq_t *cache           = NULL;   /* cached sequence values */
static size_t cache_cap       = 0;      /* capacity of cache array */
static idx_t cache_size       = 0;      /* number of elements currently cached */
static uint64_t next_candidate = 1;     /* next integer to be tested */

/* --- Sieve utilities ------------------------------------------ */

static void build_prime_table(uint64_t limit)
{
    if (limit <= prime_limit) return;          /* already enough */

    /* Allocate boolean array for sieve */
    bool *sieve = (bool*)calloc(limit + 1, sizeof(bool));
    if (!sieve) exit(1);                      /* allocation failure */
    sieve[0] = sieve[1] = true;

    /* Eratosthenes */
    for (uint64_t i = 2; i * i <= limit; ++i) {
        if (!sieve[i]) {
            for (uint64_t j = i * i; j <= limit; j += i) sieve[j] = true;
        }
    }

    /* Count primes */
    size_t cnt = 0;
    for (uint64_t i = 2; i <= limit; ++i) if (!sieve[i]) ++cnt;

    /* Allocate new prime array */
    uint64_t *new_primes = (uint64_t*)malloc(cnt * sizeof(uint64_t));
    if (!new_primes) exit(1);
    int *new_idx_arr   = (int*)calloc(limit + 1, sizeof(int));
    if (!new_idx_arr) exit(1);

    /* Fill arrays */
    size_t pos = 0;
    for (uint64_t i = 2; i <= limit; ++i) {
        if (!sieve[i]) {
            new_primes[pos] = i;
            new_idx_arr[(size_t)i] = (int)(pos + 1);   /* 1‑based index */
            ++pos;
        }
    }

    /* Replace old tables */
    free(prime_list);
    free(prime_index_arr);
    free(sieve);
    prime_list = new_primes;
    prime_index_arr = new_idx_arr;
    prime_count = cnt;
    prime_limit = limit;
}

/* Ensure that number x can be factorised with current prime table */
static void ensure_prime_limit(uint64_t x)
{
    if (x <= prime_limit) return;
    build_prime_table(x);
}

/* --- Membership test for a candidate --------------------------- */

static bool is_valid_candidate(uint64_t n)
{
    if (n == 1) return true;                  /* 1 has no prime factors */

    uint64_t tmp = n;
    uint64_t idx_list[64];
    size_t    idx_cnt = 0;

    /* Factorisation using primes up to sqrt(tmp) */
    for (size_t i = 0; i < prime_count && prime_list[i] * prime_list[i] <= tmp; ++i) {
        uint64_t p = prime_list[i];
        if (tmp % p == 0) {
            /* Record the prime index once */
            idx_list[idx_cnt++] = (uint64_t)prime_index_arr[(size_t)p];
            while (tmp % p == 0) tmp /= p;
        }
    }

    /* Remaining factor > sqrt(tmp) */
    if (tmp > 1) {
        if (tmp > prime_limit) ensure_prime_limit(tmp);
        /* After extension tmp must be <= prime_limit */
        idx_list[idx_cnt++] = (uint64_t)prime_index_arr[(size_t)tmp];
    }

    /* Check forbidden pairs (m, 2m) among the prime indices */
    for (size_t i = 0; i < idx_cnt; ++i) {
        uint64_t m = idx_list[i];
        uint64_t two_m = m << 1;
        for (size_t j = 0; j < idx_cnt; ++j) {
            if (idx_list[j] == two_m) return false;
        }
    }
    return true;
}

/* --- Cache handling -------------------------------------------- */

static void ensure_cache(idx_t up_to)
{
    if (cache_size >= up_to) return;           /* already have enough terms */

    /* Grow cache if necessary */
    if (cache_cap < (size_t)up_to) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 64;
        while (new_cap < (size_t)up_to) new_cap <<= 1;
        seq_t *new_cache = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        if (!new_cache) exit(1);               /* allocation failure */
        cache = new_cache;
        cache_cap = new_cap;
    }

    /* Initialise first term 1 if cache empty */
    if (cache_size == 0) {
        cache[cache_size++] = (seq_t)1;
        if (next_candidate == 1) ++next_candidate;
    }

    /* Generate terms until we reach 'up_to' */
    while (cache_size < up_to) {
        if (is_valid_candidate(next_candidate)) {
            cache[cache_size++] = (seq_t)next_candidate;
        }
        ++next_candidate;
    }
}

/* --- Public function ------------------------------------------- */

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;                /* out‑of‑range behaviour undefined */
    /* Initialise primes to a modest size to start with */
    if (prime_limit == 0) build_prime_table(1000);
    ensure_cache(n);
    return cache[n - 1];
}
